const deadline = deps.now() + timeoutMs;
let review: QodoReview | undefined;
let polls = 0;
for (;;) {
  polls++;
  await deps.onPoll?.();
  review = await deps.fetchReview();
  if (reviewState(review, headSha) === "complete") return { state: "complete", review, polls };
  if (deps.now() + intervalMs > deadline) return { state: "timeout", review, polls };
  await deps.sleep(intervalMs);

private async rpc(method: string, params: unknown, notify = false): Promise<unknown> {
  const body = notify ? { jsonrpc: "2.0", method, params } : { jsonrpc: "2.0", id: ++this.id, method, params };
  const res = await fetch(URL, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${this.key}`,
      "Content-Type": "application/json",
      Accept: "application/json, text/event-stream",
      ...(this.session ? { "Mcp-Session-Id": this.session } : {}),
    },
    body: JSON.stringify(body),
  });

